param([string]$Action,[Parameter(Mandatory=$true)][string]$Root,[Parameter(Mandatory=$true)][string]$Data)
$ErrorActionPreference='Stop'
# CloudDrive2 host integration. The vendor installer (Inno Setup) writes to the
# machine-wide install directory, installs the WinFsp driver, registers the
# CloudDrive2 service and terminates running processes. This recipe only
# anchors the service registration at the Piko version directory; it installs
# no driver and copies nothing outside the managed root.
$Root=[IO.Path]::GetFullPath($Root).TrimEnd('\')
$service=Join-Path $Root 'shawl.exe'
$target=Join-Path $Root 'clouddrive.exe'
$journal=Join-Path $Data 'piko-clouddrive2-service.json'
foreach ($required in @($service,$target)) {
 if (!(Test-Path -LiteralPath $required -PathType Leaf)) {throw ('Managed payload missing: '+$required)}
}
function Get-ImagePath([string]$PathName){
 $p=$PathName.Trim()
 if ($p.StartsWith('"')) {
  $end=$p.IndexOf('"',1)
  if ($end -gt 1) {$p=$p.Substring(1,$end-1)} else {$p=$p.Substring(1)}
 }
 $p
}
function Test-UnderRoot([string]$PathName){(Get-ImagePath $PathName).StartsWith($Root,[System.StringComparison]::OrdinalIgnoreCase)}
function Get-RootServices{@(Get-CimInstance Win32_Service -Filter "Name='CloudDrive2'" | Where-Object {$_.PathName -and (Test-UnderRoot $_.PathName)})}
$record=$null
if (Test-Path -LiteralPath $journal) {
 $record=Get-Content -LiteralPath $journal -Raw | ConvertFrom-Json
 if ($record.schemaVersion -ne 1) {throw 'Unsupported service ownership receipt'}
 if ($record.root -ine $Root) {throw 'Another Piko version owns the CloudDrive2 service registration; remove that version first'}
}
if ($Action -eq 'install') {
 if ($record -and $record.state -eq 'installed' -and (Get-RootServices).Count) {throw 'Service integration already installed for this version'}
 foreach ($foreign in @(Get-CimInstance Win32_Service -Filter "Name='CloudDrive2'")) {
  if (!$foreign.PathName -or !(Test-UnderRoot $foreign.PathName)) {throw ('Existing external CloudDrive2 service points outside this version ('+$foreign.PathName+'); remove it through its owner first')}
 }
 $null=[IO.Directory]::CreateDirectory($Data)
 @{schemaVersion=1;root=$Root;state='installing';started=(Get-Date).ToUniversalTime().ToString('o')} | ConvertTo-Json | Set-Content -LiteralPath $journal -Encoding UTF8
 # Same command line the vendor installer registers.
 $binpath='"'+$service+'" run --no-log -- "'+$target+'"'
 $null=& sc.exe create CloudDrive2 binpath= $binpath DisplayName= 'CloudDrive2 Service' start= auto
 if ($LASTEXITCODE -ne 0) {throw ('Service creation failed: '+$LASTEXITCODE)}
 $null=& sc.exe start CloudDrive2
 $deadline=(Get-Date).AddSeconds(120)
 $started=$false
 do {
  $running=Get-RootServices
  if ($running.Count -and $running[0].State -eq 'Running') {$started=$true;break}
  Start-Sleep -Seconds 2
 } while ((Get-Date) -lt $deadline)
 if (!$started) {
  $null=& sc.exe stop CloudDrive2
  $null=& sc.exe delete CloudDrive2
  throw 'Service did not reach the Running state under this version directory; registration was withdrawn'
 }
 @{schemaVersion=1;root=$Root;state='installed';service='CloudDrive2';binpath=$binpath;installed=(Get-Date).ToUniversalTime().ToString('o')} | ConvertTo-Json | Set-Content -LiteralPath $journal -Encoding UTF8
 Write-Output 'Installed CloudDrive2 service registration for this version'
} else {
 if (!$record -or $record.state -ne 'installed') {throw 'No owned CloudDrive2 service registration for this version'}
 $serviceEntry=Get-CimInstance Win32_Service -Filter "Name='CloudDrive2'"
 if ($serviceEntry) {
  if (!(Test-UnderRoot $serviceEntry.PathName)) {throw ('Refusing to delete externally owned service '+$serviceEntry.PathName)}
  $null=& sc.exe stop CloudDrive2
  if ($serviceEntry.ProcessId) {Stop-Process -Id $serviceEntry.ProcessId -Force -ErrorAction SilentlyContinue}
  $null=& sc.exe delete CloudDrive2
  if (Get-CimInstance Win32_Service -Filter "Name='CloudDrive2'") {throw 'Failed to delete CloudDrive2 service'}
 }
 Remove-Item -LiteralPath $journal
 Write-Output 'Removed CloudDrive2 service registration for this version'
}
